/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `create_feedback_response_notification` AFTER INSERT ON `feedback_responses` FOR EACH ROW BEGIN
            DECLARE user_email_var VARCHAR(255);
            DECLARE feedback_type_var VARCHAR(50);
            DECLARE notification_id VARCHAR(255);
            DECLARE notification_title VARCHAR(255);
            DECLARE notification_message TEXT;
            DECLARE notification_data TEXT;
            
            SELECT user_email, type
            INTO user_email_var, feedback_type_var
            FROM feedback
            WHERE id = NEW.feedback_id
            LIMIT 1;
            
            IF user_email_var IS NOT NULL THEN
                SET notification_id = CONCAT('feedbackResponse_', UNIX_TIMESTAMP(NOW()), '_', SUBSTRING(MD5(RAND()), 1, 9));
                SET notification_title = 'Response to Your Feedback';
                
                CASE feedback_type_var
                    WHEN 'suggestion' THEN
                        SET notification_message = 'The admin has responded to your suggestion. Check the feedback section for details.';
                    WHEN 'bug' THEN
                        SET notification_message = 'The admin has responded to your bug report. Check the feedback section for details.';
                    WHEN 'rating' THEN
                        SET notification_message = 'The admin has responded to your rating and feedback. Check the feedback section for details.';
                    ELSE
                        SET notification_message = 'The admin has responded to your feedback. Check the feedback section for details.';
                END CASE;
                
                SET notification_data = JSON_OBJECT(
                    'type', 'feedbackResponse',
                    'feedbackId', NEW.feedback_id,
                    'responseId', NEW.id,
                    'adminEmail', NEW.admin_email
                );
                
                INSERT INTO notifications (id, type, title, message, data, `read`, created_at, user_email)
                VALUES (
                    notification_id,
                    'feedbackResponse',
                    notification_title,
                    notification_message,
                    notification_data,
                    0,
                    NOW(),
                    user_email_var
                );
            END IF;
        END */;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
