--
-- Table structure for table `items`
--

DROP TABLE IF EXISTS `items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `items` (
  `id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `description` text COLLATE utf8mb4_general_ci,
  `category` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` enum('lost','found') COLLATE utf8mb4_general_ci NOT NULL,
  `status` enum('active','inactive','claimed','returned','resolved','pending_turnin','fake_report') COLLATE utf8mb4_general_ci DEFAULT 'active',
  `location` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `date_reported` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `date_lost_found` date DEFAULT NULL,
  `reporter_id` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `reporter_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `reporter_email` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `reporter_department` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `detected_objects` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `detected_categories` varchar(300) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `turnin_deadline` datetime DEFAULT NULL COMMENT '12-hour deadline for found items to be turned in to SSC Office',
  `turnin_status` enum('pending','confirmed','expired') COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Status of turn-in: pending, confirmed by SSC, or expired',
  `turnin_confirmed_at` datetime DEFAULT NULL COMMENT 'When SSC Office confirmed receiving the item',
  `turnin_confirmed_by` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Email of SSC admin who confirmed turn-in',
  PRIMARY KEY (`id`),
  KEY `idx_type` (`type`),
  KEY `idx_status` (`status`),
  KEY `idx_category` (`category`),
  KEY `idx_reporter_email` (`reporter_email`),
  KEY `idx_date_reported` (`date_reported`),
  KEY `idx_location` (`latitude`,`longitude`),
  KEY `idx_detected_objects` (`detected_objects`),
  KEY `idx_detected_categories` (`detected_categories`),
  KEY `idx_turnin_deadline` (`turnin_deadline`,`status`,`type`),
  KEY `idx_turnin_status` (`turnin_status`),
  FULLTEXT KEY `idx_search` (`title`,`description`,`detected_objects`,`detected_categories`),
  CONSTRAINT `items_chk_1` CHECK (json_valid(`images`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `items`
--

LOCK TABLES `items` WRITE;
/*!40000 ALTER TABLE `items` DISABLE KEYS */;
INSERT INTO `items` VALUES ('found-1760279659209-rhty5j28c','Powerbankkk','A white power bank with \"RAPPO\" branding embossed on the top left and a charging indicator bar showing \"20000mAh\" on the right side. The power bank is resting on a white, textured surface that appears to be fabric. There is also a small icon resembling a pointing finger on the lower left side of the power bank.','electronics','found','active','1, Bato, Bicol, Philippines',13.35676340,123.37537140,'2025-10-12 14:34:20','2025-10-12','ccserrano@my.cspc.edu.ph','Charles Christian Serrano','ccserrano@my.cspc.edu.ph','Information Technology','[\"https://api.lostfound.systems/uploads/1760279630750_17spttce.jpg\"]','[{\"name\":\"power bank\",\"confidence\":0.98},{\"name\":\"charging indicator\",\"confidence\":0.95},{\"name\":\"branding\",\"confidence\":0.9},{\"name\":\"pointing finger icon\",\"confidence\":0.85}]','[\"electronics\",\"portable charger\"]','2025-10-12 14:34:20','2025-10-12 14:34:20',NULL,NULL,NULL,NULL),('found-1760335901341-kxohfactb','wallet','A close-up shot of a hand holding a crocheted circular item adorned with red, yellow, and green concentric rings against a backdrop of blurred green foliage and tree trunks. The item appears to be a small pouch or coin purse, with a black knitted center and radiating colorful crochet work. Attached to it is a keyring with a decorative element that resembles a strawberry. There is also a strand of white beads with amber accents, and a small, metallic charm shaped like a cross.','Accessories','found','active','CC9H+JG8, Iriga City, Bicol, Philippines',13.41864880,123.42906880,'2025-10-13 06:11:41','2025-10-13','kabuenconsejo@my.cspc.edu.ph','Kaila Buenconsejo','kabuenconsejo@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1760335810993_hygtt8bs.jpg\"]','[{\"name\":\"crocheted coin purse\",\"confidence\":0.98},{\"name\":\"keychain\",\"confidence\":0.97},{\"name\":\"strawberry charm\",\"confidence\":0.95},{\"name\":\"beaded strand\",\"confidence\":0.93},{\"name\":\"metallic charm\",\"confidence\":0.9},{\"name\":\"hand\",\"confidence\":0.99}]','[\"Accessories\",\"Crafts\",\"Jewelry\",\"Horticulture\"]','2025-10-13 06:11:41','2025-10-13 06:11:41',NULL,NULL,NULL,NULL),('found-1760337229353-86xeylzvw','Diamond ring','A close-up, angled shot of a silver ring with a clear gemstone is centered on a textured, dark gray surface. The ring band is smooth and rounded, with the gemstone prominently displayed at the top. The gemstone appears to be faceted and reflects light, suggesting it is likely a diamond or a clear cubic zirconia. The background has a rough, almost pebbled texture and is dark, which helps the shiny ring stand out.','Jewelry','found','active','CSPC Entry Road, Nabua, Bicol, Philippines',13.40596300,123.37545400,'2025-10-13 06:33:49','2025-10-13','anrancapollo@my.cspc.edu.ph','Andrea nicole Rancapollo','anrancapollo@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1760337194293_xlynp54i.jpg\"]','[{\"name\":\"ring\",\"confidence\":0.99},{\"name\":\"gemstone\",\"confidence\":0.98}]','[\"Jewelry\",\"Jewelry\",\"Gemstone\"]','2025-10-13 06:33:49','2025-10-13 06:33:49',NULL,NULL,NULL,NULL),('found-1760421621336-lsf8dwy0u','Charger','A white charging brick with a coiled white cable is shown lying on a textured light-colored surface. The charging brick has a flat, rectangular shape with a slightly rounded top. It features two metal prongs extending from the bottom. The white cable connects to the top of the brick and is coiled in a loose spiral for part of its length. A black, spiral-shaped cable protector is wrapped around the cable near the charging brick. The surface appears to be made of tiles or a similar material with visible grout lines.','Electronics','found','active','Poblacion Road, Nabua, Bicol, Philippines',13.40566930,123.37722690,'2025-10-14 06:00:21','2025-10-14','loroxas@my.cspc.edu.ph','Loren Roxas','loroxas@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1760421590222_0ehzcgok.jpg\"]','[{\"name\":\"charger\",\"confidence\":0.99},{\"name\":\"cable\",\"confidence\":0.98},{\"name\":\"cable protector\",\"confidence\":0.97}]','[\"Electronics\",\"Charger\",\"Cable\"]','2025-10-14 06:00:21','2025-10-14 06:00:21',NULL,NULL,NULL,NULL),('found-1760425803485-3kwm4i00t','Umbrella','A folded, dark green umbrella lies horizontally on a surface with a patterned wood grain design. The umbrella is closed and secured with a fabric band. The handle, which is black and cylindrical, is visible on the left side, with a black strap attached.','Accessory','found','returned','C95G+348, Nabua, Bicol, Philippines',13.40783740,123.37543980,'2025-10-14 07:10:04','2025-10-14','gwbuenconsejo@my.cspc.edu.ph','Gwyneth Buenconsejo','gwbuenconsejo@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1760425556673_5f0ahlue.jpg\"]','[{\"name\":\"umbrella\",\"confidence\":0.99}]','[\"Accessory\",\"Outdoor gear\"]','2025-10-14 07:10:04','2025-10-14 07:18:16',NULL,NULL,NULL,NULL),('found-1760440623259-r0dqq7guf','Laptop','Tuff gaming laptop !!!','Keys','found','active','Camia Street, Iriga City, Bicol, Philippines',13.41907430,123.41242550,'2025-10-14 11:17:04','2025-10-14','darolea@my.cspc.edu.ph','Darryl kyle Olea','darolea@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1760440287449_41p3ur6g.jpg\"]','[{\"name\":\"Keys\",\"confidence\":0.8},{\"name\":\"Laptop\",\"confidence\":0.8}]','[\"Keys\"]','2025-10-14 11:17:04','2025-10-14 11:17:04',NULL,NULL,NULL,NULL),('found-1760443686924-jiea10pw3','tumbler','A light purple water bottle with a flip-up straw is placed on a table covered with a patterned tablecloth. The background is a plain, light-colored wall.','Drinkware','found','active','Narra St., Iriga City, Bicol, Philippines',13.42360190,123.42202300,'2025-10-14 12:08:08','2025-10-14','chfrondozo@my.cspc.edu.ph','Christine Joy Frondozo','chfrondozo@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1760443604136_wghq0ffb.jpg\"]','[{\"name\":\"water bottle\",\"confidence\":0.98}]','[\"Drinkware\",\"Container\",\"Kitchenware\"]','2025-10-14 12:08:08','2025-10-14 12:08:08',NULL,NULL,NULL,NULL),('found-1760448000371-a56hqmoz5','Tote bag','A person is sitting at a table outdoors, holding a black tote bag with white text that says \"Have a good time.\" The bag has a green keychain with a red and white bobber attached. The person is wearing light-colored jeans and a white t-shirt. A pair of black headphones rests on the table. The background features lush green foliage and a patio floor made of interlocking stones.','Fashion','found','active','Iriga City - Sagrada - San Ramon - Hanawan Road, Iriga City, Bicol, Philippines',13.44861870,123.40357720,'2025-10-14 13:20:01','2025-10-14','johmejia@my.cspc.edu.ph','John Christian Mejia','johmejia@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1760447962770_qjef36hq.jpg\"]','[{\"name\":\"tote bag\",\"confidence\":0.99},{\"name\":\"headphones\",\"confidence\":0.98},{\"name\":\"jeans\",\"confidence\":0.97},{\"name\":\"t-shirt\",\"confidence\":0.96},{\"name\":\"keychain\",\"confidence\":0.93},{\"name\":\"table\",\"confidence\":0.9},{\"name\":\"chair\",\"confidence\":0.88}]','[\"Fashion\",\"Accessories\",\"Outdoor\",\"Lifestyle\"]','2025-10-14 13:20:01','2025-10-14 13:20:01',NULL,NULL,NULL,NULL),('found-1761120948126-2fp1iifwt','Umbrella','A person is holding a partially closed pink umbrella. The umbrella has a black interior and a pink handle. The background shows a tiled floor and a wall with blue and black stripes.  Part of another person\'s legs can be seen in the upper left corner.','Accessory','found','active','Poblacion Road, Nabua, Bicol, Philippines',13.40567280,123.37715920,'2025-10-22 08:15:48','2025-10-22','loroxas@my.cspc.edu.ph','Loren Roxas','loroxas@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1761120926205_ye3jmcdt.jpg\"]','[{\"name\":\"umbrella\",\"confidence\":0.97},{\"name\":\"hand\",\"confidence\":0.96},{\"name\":\"wall\",\"confidence\":0.85},{\"name\":\"floor\",\"confidence\":0.8}]','[\"Accessory\",\"Weather protection\"]','2025-10-22 08:15:48','2025-11-24 20:36:19',NULL,NULL,NULL,NULL),('found-1761497879702-3b6pf2i31','Missing a4tech','Black mouse','Computer peripherals','found','active','1, Bato, Bicol, Philippines',13.35658050,123.37573950,'2025-10-26 16:57:59','2025-10-26','ccserrano@my.cspc.edu.ph','Charles Christian Serrano','ccserrano@my.cspc.edu.ph','Information Technology','[\"https://api.lostfound.systems/uploads/1761497841214_g5asfhmu.jpg\"]','[{\"name\":\"computer mouse\",\"confidence\":0.98},{\"name\":\"laptop keyboard\",\"confidence\":0.95}]','[\"Computer peripherals\",\"Electronics\"]','2025-10-26 16:57:59','2025-10-26 16:57:59',NULL,NULL,NULL,NULL),('found-1761499188994-6p9cm615k','Found Accessory','A close-up shot of a gray, textured object, possibly a protective case or a handle, held by a hand. The object has embossed markings that appear to be a series of horizontal lines of varying lengths, potentially representing a scale or pattern. The texture is granular, resembling leather or a similar synthetic material. The background is blurred, with hints of other objects like a laptop and possibly a mug or container.','Accessory','found','active','1, Bato, Bicol, Philippines',13.35657290,123.37574830,'2025-10-26 17:19:49','2025-10-26','anescuro@my.cspc.edu.ph','Angeline Escuro','anescuro@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1761499169611_r6nkh49t.jpg\"]','[{\"name\":\"textured case\",\"confidence\":0.98},{\"name\":\"hand\",\"confidence\":0.85},{\"name\":\"embossed lines\",\"confidence\":0.9}]','[\"Accessory\",\"Container\",\"Personal care\"]','2025-10-26 17:19:49','2025-10-26 17:19:49',NULL,NULL,NULL,NULL),('found-1761550998142-1sq4vgssj','Gaming mouse','A white and blue computer mouse with red buttons is shown from a top-down angle. The mouse has a sleek design with some graphic elements and text on it, including the word \"ZEUS\" prominently displayed. The mouse rests on a dark, textured surface, possibly a mousepad or desk.','Electronics','found','active','Poblacion Road, Nabua, Bicol, Philippines',13.40570510,123.37705190,'2025-10-27 07:43:18','2025-10-27','loroxas@my.cspc.edu.ph','Loren Roxas','loroxas@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1761550810998_8go8r7e9.jpg\"]','[{\"name\":\"computer mouse\",\"confidence\":0.99}]','[\"Electronics\",\"Computer accessories\"]','2025-10-27 07:43:18','2025-11-25 09:14:11',NULL,NULL,NULL,NULL),('found-1761636657613-02xafv2w2','Found Office supplies','A silver-colored stapler is lying on a light-colored, textured surface, possibly a desk or table. The stapler is open, revealing its internal mechanism. A blue plastic piece is visible at the bottom of the stapler. In the background, a black cable is partially visible on the left. The surface appears worn and has some dark marks and faint lines. A portion of a light-colored shoe with green accents is visible at the bottom left corner of the image.','Office supplies','found','returned','CSPC Entry Road, Nabua, Bicol, Philippines',13.40562440,123.37481350,'2025-10-28 07:30:57','2025-10-28','secapistrano@my.cspc.edu.ph','Sean Matthew Capistrano','secapistrano@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1761636604356_3szqt39s.jpg\"]','[{\"name\":\"stapler\",\"confidence\":0.99},{\"name\":\"desk\",\"confidence\":0.8},{\"name\":\"cable\",\"confidence\":0.75},{\"name\":\"shoe\",\"confidence\":0.7}]','[\"Office supplies\",\"Stationery\",\"Desk\"]','2025-10-28 07:30:57','2025-11-25 09:16:00',NULL,NULL,NULL,NULL),('found-1762320268041-p6xlee42f','Phone','A close-up shot of a pink iPhone case adorned with a pattern of bows. The case has a cut-out for the camera module, which shows three lenses and the text \'50MP AI CAMERA\'. The bows are depicted in various sizes, some in pink and others in a lighter, outlined style. The word \'Bowknot\' is printed in black text near the bottom of the case.','Electronics','found','active','Poblacion Road, Nabua, Bicol, Philippines',13.40569480,123.37710160,'2025-11-05 05:24:29','2025-11-05','eddimacali@my.cspc.edu.ph','Edgardo Dimacali','eddimacali@my.cspc.edu.ph','Education','[\"https://api.lostfound.systems/uploads/1762320224782_e18y5oxi.jpg\"]','[{\"name\":\"phone case\",\"confidence\":0.99},{\"name\":\"camera module\",\"confidence\":0.98},{\"name\":\"bow pattern\",\"confidence\":0.97},{\"name\":\"text \'Bowknot\'\",\"confidence\":0.95}]','[\"Electronics\",\"Accessories\",\"Phone case\"]','2025-11-05 05:24:29','2025-11-05 05:24:29',NULL,NULL,NULL,NULL),('found-1764575967280-nth3hy1c9','Light brown wallet','A light brown, textured wallet with a silver-toned emblem is shown against a white background. A wrist strap extends from the left side of the wallet.','Accessory','found','active','1, Nabua, Bicol, Philippines',13.40935170,123.37212990,'2025-12-01 07:59:28','2025-12-01','chfrondozo@my.cspc.edu.ph','Christine Joy Frondozo','chfrondozo@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1764575954393_0ex2n4kl.jpg\"]','[{\"name\":\"wallet\",\"confidence\":0.99},{\"name\":\"wrist strap\",\"confidence\":0.97},{\"name\":\"emblem\",\"confidence\":0.96}]','[\"Accessory\",\"Fashion\"]','2025-12-01 07:59:28','2025-12-01 19:05:28','2025-12-01 19:59:27','pending',NULL,NULL),('lost-1760274158959-d9y20estc','Id','A student ID card from Camarines Sur Polytechnic Colleges, for a Bachelor of Science in Information Technology (BSIT) student named Loren De Leon Roxas. The card features a photo of the student, her name, address, date of birth, signature, and various institutional markings and certifications.','identification','lost','active','1, Bato, Bicol, Philippines',13.35673920,123.37532280,'2025-10-12 13:02:40','2025-10-12','ccserrano@my.cspc.edu.ph','Charles Christian Serrano','ccserrano@my.cspc.edu.ph','Information Technology','[\"https://api.lostfound.systems/uploads/1760274142566_p1q7wnkt.jpg\"]','[{\"name\":\"student ID card\",\"confidence\":0.99},{\"name\":\"photograph\",\"confidence\":0.98},{\"name\":\"name\",\"confidence\":0.95},{\"name\":\"institution logo\",\"confidence\":0.92},{\"name\":\"signature\",\"confidence\":0.9},{\"name\":\"barcode\",\"confidence\":0.85}]','[\"identification\",\"education\",\"document\"]','2025-10-12 13:02:40','2025-10-12 13:02:40',NULL,NULL,NULL,NULL),('lost-1760335689609-klgc3pmwd','crochet wallet with keychain','A circular, crocheted coin purse with Rasta-colored stripes (black, green, red, and yellow) is attached to a keychain. The keychain also features a small wooden charm resembling a strawberry, along with a strand of small rosary white beads.','Accessories','lost','active','CC9H+JG8, Iriga City, Bicol, Philippines',13.41865110,123.42907260,'2025-10-13 06:08:11','2025-10-13','gwbuenconsejo@my.cspc.edu.ph','Gwyneth Buenconsejo','gwbuenconsejo@my.cspc.edu.ph','CSPC Student','[\"https://api.lostfound.systems/uploads/1760335613554_n818sq0z.jpg\"]','[{\"name\":\"crocheted coin purse\",\"confidence\":0.99},{\"name\":\"keychain\",\"confidence\":0.99},{\"name\":\"strawberry charm\",\"confidence\":0.95},{\"name\":\"beads\",\"confidence\":0.9}]','[\"Accessories\",\"Handmade\"]','2025-10-13 06:08:11','2025-10-13 06:08:11',NULL,NULL,NULL,NULL),('lost-1760337134414-geneqogtq','Ring','A close-up shot captures a diamond engagement ring being held between a person\'s fingers. The ring features a silver band with small diamonds embedded along its surface, leading to a prominent central diamond that sparkles under the light. The background is a softly blurred neutral tone, directing all attention to the intricate details of the ring.','Jewelry','lost','active','CSPC Entry Road, Nabua, Bicol, Philippines',13.40601740,123.37521140,'2025-10-13 06:32:14','2025-10-13','frlibreja@my.cspc.ed