/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `after_item_insert_notification` AFTER INSERT ON `items` FOR EACH ROW BEGIN
    INSERT INTO notifications_web (
        user_email,
        title,
        message,
        type,
        entity_type,
        entity_id,
        is_read,
        created_at,
        updated_at
    )
    SELECT 
        email,
        CONCAT('New ', UPPER(NEW.status), ' Item Reported'),
        CONCAT(
            'A new ',
            NEW.status,
            ' item has been reported: ''',
            COALESCE(NEW.title, 'Untitled'),
            '''. Reporter: ',
            COALESCE(NEW.reporter_name, 'Unknown'),
            ' (',
            COALESCE(NEW.reporter_email, 'No email'),
            '). Please review this item and take appropriate action.'
        ),
        'item',
        'item',
        NEW.id,
        0,
        NOW(),
        NOW()
    FROM admin_role
    WHERE role IN ('super_admin', 'admin', 'staff');
END */;;
DELIMITER ;
