--
-- Table structure for table `matches`
--

DROP TABLE IF EXISTS `matches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `matches` (
  `id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `status` enum('pending','accepted','rejected','resolved') COLLATE utf8mb4_general_ci DEFAULT 'pending',
  `score` decimal(3,2) NOT NULL,
  `lost_item_id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `lost_item_title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `lost_item_description` text COLLATE utf8mb4_general_ci,
  `lost_item_category` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `lost_item_location` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `lost_item_latitude` decimal(10,8) DEFAULT NULL,
  `lost_item_longitude` decimal(11,8) DEFAULT NULL,
  `lost_item_date_reported` timestamp NULL DEFAULT NULL,
  `lost_item_date_lost_found` date DEFAULT NULL,
  `lost_item_reporter_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `lost_item_reporter_email` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `lost_item_reporter_department` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `lost_item_images` longtext COLLATE utf8mb4_general_ci,
  `lost_item_detected_objects` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `lost_item_detected_categories` varchar(300) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `found_item_id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `found_item_title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `found_item_description` text COLLATE utf8mb4_general_ci,
  `found_item_category` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `found_item_location` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `found_item_latitude` decimal(10,8) DEFAULT NULL,
  `found_item_longitude` decimal(11,8) DEFAULT NULL,
  `found_item_date_reported` timestamp NULL DEFAULT NULL,
  `found_item_date_lost_found` date DEFAULT NULL,
  `found_item_reporter_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `found_item_reporter_email` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `found_item_reporter_department` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `found_item_images` longtext COLLATE utf8mb4_general_ci,
  `found_item_detected_objects` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `found_item_detected_categories` varchar(300) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_match` (`lost_item_id`,`found_item_id`),
  KEY `idx_status` (`status`),
  KEY `idx_score` (`score`),
  KEY `idx_lost_item` (`lost_item_id`),
  KEY `idx_found_item` (`found_item_id`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

