DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `after_match_insert_notification` AFTER INSERT ON `matches` FOR EACH ROW BEGIN
    INSERT INTO notifications_web (
        user_email,
        title,
        message,
        type,
        entity_type,
        entity_id,
        is_read,
        created_at,
        updated_at
    )
    SELECT 
        email,
        'New Match Found',
        CONCAT(
            'A new potential match has been found between lost item ''',
            COALESCE(NEW.lost_item_title, 'Unknown'),
            ''' and found item ''',
            COALESCE(NEW.found_item_title, 'Unknown'),
            ''' with a match score of ',
            ROUND(NEW.score * 100, 2),
            '%. Please review this match and take appropriate action.'
        ),
        'match',
        'match',
        NEW.id,
        0,
        NOW(),
        NOW()
    FROM admin_role
    WHERE role IN ('super_admin', 'admin', 'staff');
END */;;
DELIMITER ;
