INSERT INTO `notifications` VALUES ('claimStatus_1764615900_8aa72478f','claimStatus','Claim Request Status Updated','Your claim request for \"Lost Accessory\" has been received and is currently pending review. Our team will assess your submission shortly.','{\"type\": \"claimStatus\", \"itemId\": \"lost-1764575881776-7y7889meq\", \"claimId\": \"98d6b8a5-fe2f-4d1e-a8a0-47c133dc7b50\", \"itemTitle\": \"Lost Accessory\", \"newStatus\": \"pending\", \"oldStatus\": \"resolved\", \"statusLabel\": \"Pending Review\"}',0,0,'2025-12-02 03:05:00','secapistrano@my.cspc.edu.ph'),('claimStatus_1764615915_78f8b8470','claimStatus','Claim Request Status Updated','Congratulations! Your claim request for \"Lost Accessory\" has been approved. Please check your email for further instructions regarding item retrieval.','{\"type\": \"claimStatus\", \"itemId\": \"lost-1764575881776-7y7889meq\", \"claimId\": \"98d6b8a5-fe2f-4d1e-a8a0-47c133dc7b50\", \"itemTitle\": \"Lost Accessory\", \"newStatus\": \"approved\", \"oldStatus\": \"pending\", \"statusLabel\": \"Approved\"}',0,0,'2025-12-02 03:05:15','secapistrano@my.cspc.edu.ph'),('claimStatus_1764615928_3378e43fc','claimStatus','Claim Request Status Updated','Your claim request for \"Lost Accessory\" has been declined. Please check your email for the reason and further guidance.','{\"type\": \"claimStatus\", \"itemId\": \"lost-1764575881776-7y7889meq\", \"claimId\": \"98d6b8a5-fe2f-4d1e-a8a0-47c133dc7b50\", \"itemTitle\": \"Lost Accessory\", \"newStatus\": \"rejected\", \"oldStatus\": \"approved\", \"statusLabel\": \"Rejected\"}',0,0,'2025-12-02 03:05:28','secapistrano@my.cspc.edu.ph'),('claimStatus_1764615939_665bb5464','claimStatus','Claim Request Status Updated','Your claim request for \"Lost Accessory\" has been successfully resolved. The item has been returned to you. Thank you for your patience.','{\"type\": \"claimStatus\", \"itemId\": \"lost-1764575881776-7y7889meq\", \"claimId\": \"98d6b8a5-fe2f-4d1e-a8a0-47c133dc7b50\", \"itemTitle