--
-- Table structure for table `notifications_web`
--

DROP TABLE IF EXISTS `notifications_web`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notifications_web` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_email` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `user_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `message` text COLLATE utf8mb4_general_ci NOT NULL,
  `type` enum('item','claim','match','system','announcement') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'system',
  `entity_type` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Type of entity (item, claim, match, etc.)',
  `entity_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'ID of the related entity',
  `is_read` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = unread, 1 = read',
  `priority` enum('low','medium','high','urgent') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'medium',
  `action_url` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'URL to redirect when notification is clicked',
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT 'Additional data in JSON format',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1771 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

