INSERT INTO `notifications_web` VALUES (1,'admin@my.cspc.edu.ph','Admin','System Update Notification','System maintenance scheduled:\nDate: January 30, 2025\nTime: 2:00 AM - 4:00 AM\n All services will be temporarily unavailable\n Please save your work before the maintenance window','system',NULL,NULL,0,'high','/admin/maintenance',NULL,NULL,NULL),(2,'admin@my.cspc.edu.ph','Admin','New Policy Update','Important policy changes effective immediately:\n\nItem Claim Process:\n Valid ID required for all claims\n Maximum claim period: 30 days\n Items unclaimed after 30 days will be donated\n\nReporting Requirements:\n Detailed description mandatory\n Photo evidence recommended\n Contact information must be verified','announcement',NULL,NULL,0,'high','/admin/policies',NULL,NULL,NULL),(3,'admin@my.cspc.edu.ph','Admin','Security Alert','Important security update:\n\nNew Security Measures:\n Two-factor authentication enabled\n Password requirements updated\n Session timeout reduced to 30 minutes\n\nAction Required:\n Update your password immediately\n Enable 2FA in your profile settings\n Review recent login activity','system',NULL,NULL,0,'urgent','/admin/security',NULL,NULL,NULL),(4,'admin@my.cspc.edu.ph','Admin','System Update Notification','System maintenance scheduled:\nDate: January 30, 2025\nTime: 2:00 AM - 4:00 AM\n All services will be temporarily unavailable\n Please save your work before the maintenance window','system',NULL,NULL,0,'high','/admin/maintenance',NULL,NULL,NULL),(5,'admin@my.cspc.edu.ph','Admin','New Policy Update','Important policy changes effective immediately:\n\nItem Claim Process:\n Valid ID required for all claims\n Maximum claim period: 30 days\n Items unclaimed after 30 days will be donated\n\nReporting Requirements:\n Detailed description mandatory\n Photo evidence recommended\n Contact information must be verified','announcement',NULL,NULL,0,'high','/admin/policies',NULL,NULL,NULL),(6,'admin@my.cspc.edu.ph','Admin','Security Alert','Important security update:\n\nNew Security Measures:\n Two-factor authentication enabled\n Password requirements updated\n Session timeout reduced to 30 minutes\n\nAction Required:\n Update your password immediately\n Enable 2FA in your profile settings\n Review recent login activity','system',NULL,NULL,0,'urgent','/admin/security',NULL,NULL,NULL),(9,'test@my.cspc.edu.ph','Test User','Item Reported Successfully','Your lost item \'Lost MacBook Pro 16-inch\' has been reported and is now being processed.','item','item','ITEM-68d962b4aa070',0,'medium','http://localhost:8080/items/view/ITEM-68d962b4aa070','{\"item_title\":\"Lost MacBook Pro 16-inch\",\"item_type\":\"lost\",\"item_category\":\"Electronics\"}','2025-09-29 00:30:44','2025-09-29 00:30:44'),(10,'test@my.cspc.edu.ph','Test User','Potential Match Found!','We found a potential match for your lost item. A found item \'Found Student ID - John Doe\' matches your description.','match','match','MATCH-68d962b4b5a86',0,'high','http://localhost:8080/matches/view/MATCH-68d962b4b5a86','{\"match_score\":92.5,\"user_item_type\":\"lost\",\"matched_item_title\":\"Found Student ID - John Doe\",\"matched_item_type\":\"found\"}','2025-09-29 00:30:44','2025-09-29 00:30:44'),(11,'test@my.cspc.edu.ph','Test User','Claim Status Updated','Congratulations! Your claim has been approved. Please proceed to collect your item.','claim','claim','CLAIM-68d962b4b620d',0,'urgent','http://localhost:8080/claims/view/CLAIM-68d962b4b620d','{\"claim_status\":\"approved\",\"item_title\":\"Found Wallet with Cash\"}','2025-09-29 00:30:44','2025-09-29 00:30:44'),(12,'test@my.cspc.edu.ph','Test User','New Announcement: System Maintenance Scheduled','The Lost & Found system will undergo scheduled maintenance on Sunday from 2:00 AM to 4:00 AM. During this time, the system may be temporarily unavailable. We apologize for any inconvenience.','announcement','announcement','ANN-68d962b4b67b5',0,'medium','http://localhost:8080/announcements/view/ANN-68d962b4b67b5','{\"an