DROP TABLE IF EXISTS `support_ticket_responses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `support_ticket_responses` (
  `id` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `ticket_id` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `responder_email` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `responder_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `responder_type` enum('support_staff','super_admin') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'support_staff',
  `message` text COLLATE utf8mb4_general_ci NOT NULL,
  `attachment_url` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `attachment_filename` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_internal` tinyint(1) DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ticket_id` (`ticket_id`),
  KEY `idx_responder_email` (`responder_email`),
  KEY `idx_created_at` (`created_at`),
  CONSTRAINT `support_ticket_responses_ibfk_1` FOREIGN KEY (`ticket_id`) REFERENCES `support_tickets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

