/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `after_support_ticket_insert_notification` AFTER INSERT ON `support_tickets` FOR EACH ROW BEGIN
    INSERT INTO notifications_web (
        user_email,
        title,
        message,
        type,
        entity_type,
        entity_id,
        is_read,
        created_at,
        updated_at
    )
    SELECT 
        ar.email,
        'New Support Ticket Created',
        CONCAT(
            'A new support ticket has been created by ',
            COALESCE(NEW.user_name, 'Unknown'),
            ' (',
            COALESCE(NEW.user_email, 'No email'),
            ') with the subject: "',
            COALESCE(NEW.subject, 'No subject'),
            '", category: ',
            COALESCE(UPPER(NEW.category), 'OTHER'),
            ', and priority level: ',
            COALESCE(UPPER(NEW.priority), 'MEDIUM'),
            '. Please review and respond to this ticket promptly to assist the user.'
        ),
        'system',
        'support_ticket',
        NEW.id,
        0,
        NOW(),
        NOW()
    FROM admin_role ar
    WHERE ar.role IN ('super_admin', 'admin', 'staff');
END */;;
DELIMITER ;
